    descriptionAdvanced: {
      de: "Die Ruinen von Karthago, einst das Zentrum einer der mächtigsten Zivilisationen der Antike, erstrecken sich über den Hügel von Byrsa und die Küstenebene nordöstlich von Tunis. Die Stadt wurde im 9. Jahrhundert v. Chr. von phönizischen Siedlern aus Tyrus gegründet und entwickelte sich zu einer dominierenden Handelsmacht im Mittelmeerraum. Nach den drei Punischen Kriegen wurde Karthago im Jahr 146 v. Chr. von den Römern vollständig zerstört, später jedoch unter Augustus als römische Kolonie wiederaufgebaut. Heute können Besucher die Überreste verschiedener Epochen besichtigen, darunter die punischen Häfen, die monumentalen Antoninus-Pius-Thermen und das römische Amphitheater. Das Gelände wurde 1979 in die UNESCO-Welterbeliste aufgenommen und ist ein Symbol für den kulturellen Reichtum Tunesiens. Die archäologischen Ausgrabungen auf dem Byrsa-Hügel bieten zudem einen spektakulären Blick auf den Golf von Tunis.",
      hu: "Karthágó romjai, amely egykor az antik világ egyik leghatalmasabb civilizációjának központja volt, a Byrsa-dombon és a Tuniszi-öböl menti síkságon terülnek el. A várost a Kr. e. 9. században alapították Türoszból érkező föníciai telepesek, és hamarosan a Földközi-tenger uralkodó kereskedelmi hatalmává vált. A három pun háborút követően, Kr. e. 146-ban a rómaiak teljesen elpusztították, de később, Augustus császár alatt római coloniaként újjáépült. Ma a látogatók különböző korszakok maradványait tekinthetik meg, többek között a pun kikötőket, Antoninus Pius monumentális termáit és a római amfiteátrumot. A helyszín 1979 óta az UNESCO Világörökség része, és Tunézia kulturális örökségének egyik legfontosabb szimbóluma. A Byrsa-dombon végzett ásatások nemcsak történelmi kincseket, hanem lenyűgöző panorámát is kínálnak a tengerre.",
      ro: "Ruinele Cartaginei, cândva centrul uneia dintre cele mai puternice civilizații ale antichității, se întind pe colina Byrsa și pe câmpia de coastă la nord-est de Tunis. Orașul a fost fondat în secolul al IX-lea î.Hr. de coloniști fenicieni din Tir, evoluând rapid într-o putere comercială dominantă în Marea Mediterană. După cele trei războaie punice, Cartagina a fost distrusă complet de romani în anul 146 î.Hr., fiind ulterior reconstruită ca colonie romană sub împăratul Augustus. Astăzi, vizitatorii pot explora vestigii din diverse epoci, inclusiv porturile punice, monumentalele Terme ale lui Antoninus Pius și amfiteatrul roman. Situl a fost inclus în lista Patrimoniului Mondial UNESCO în anul 1979 și reprezintă un simbol al bogăției culturale a Tunisiei. Excavațiile arheologice de pe colina Byrsa oferă o perspectivă spectaculoasă asupra Golfului Tunis.",
      en: "The ruins of Carthage, once the epicenter of one of antiquity's most formidable civilizations, sprawl across Byrsa Hill and the coastal plain northeast of Tunis. Founded in the 9th century BC by Phoenician settlers from Tyre, the city rose to become the dominant maritime and commercial power in the Mediterranean. Following the three Punic Wars, Carthage was utterly destroyed by the Romans in 146 BC, only to be refounded as a Roman colony under Augustus. Today, visitors can examine remnants from multiple eras, including the unique circular Punic ports, the monumental Baths of Antoninus, and the Roman amphitheater. The site was designated a UNESCO World Heritage site in 1979 and stands as a primary symbol of Tunisia's historical depth. The archaeological zone on Byrsa Hill also provides a commanding view of the Gulf of Tunis and the surrounding landscape.",
      es: "Las ruinas de Cartago son uno de los testimonios históricos más importantes del Mediterráneo y documentan el ascenso y caída de una antigua potencia mundial. La ciudad, fundada por los fenicios en el siglo IX a.C., libró una encarnizada lucha contra Roma en las Guerras Púnicas. Hoy en día, los yacimientos arqueológicos, declarados Patrimonio de la Humanidad por la UNESCO, incluyen termas romanas, puertos antiguos y villas. Los visitantes pueden apreciar las impresionantes dimensiones de la antigua metrópoli comercial. En la clase K8, los alumnos aprenden la importancia geopolítica de esta lucha de poder en el Mediterráneo.",
      pt: "As ruínas de Cartago são um dos testemunhos históricos mais importantes do Mediterrâneo e documentam a ascensão e queda de uma antiga potência mundial. A cidade, fundada pelos fenícios no século IX a.C., travou uma luta encarniçada contra Roma nas Guerras Púnicas. Hoje em dia, os sítios arqueológicos, declarados Património Mundial pela UNESCO, incluem termas romanas, portos antigos e villas. Os visitantes podem apreciar as impressionantes dimensões da antiga metrópole comercial. Na turma K8, os alunos aprendem a importância geopolítica desta luta de poder no Mediterrâneo.",
      fr: "Les ruines de Carthage sont l'un des témoignages historiques les plus importants de la Méditerranée et documentent l'ascension et la chute d'une ancienne puissance mondiale. La ville, fondée par les Phéniciens au IXe siècle av. J.-C., a mené une lutte acharnée contre Rome lors des guerres puniques. Aujourd'hui, les sites archéologiques, classés au patrimoine mondial de l'UNESCO, comprennent des thermes romains, des ports antiques et des villas. Les visiteurs peuvent apprécier les dimensions impressionnantes de l'ancienne métropole commerciale. Dans la classe K8, les élèves apprennent l'importance géopolitique de cette lutte de pouvoir en Méditerranée.",
    },
