      hu: "Ammaedara ókori római erődvárosa, amely Észak-Afrika egyik legnagyobb bizánci várának ad otthont.",
      ro: "Orașul cetate roman antic Ammaedara, care găzduiește unul dintre cele mai mari castele bizantine din Africa de Nord.",
