      pt: ["O arco do triunfo de Antonino Pio data do ano 158 d.C.", "A cidade foi elevada a município por volta de 150 d.C.", "As termas cobriam 1.000 metros quadrados.", "O aqueduto tinha 10 quilómetros de extensão.", "A população era de cerca de 8.000 habitantes.", "A basílica tinha cinco naves e data do século VI."],
