      en: ["Originally built in the 15th century, second court added in the 19th", "Consists of approximately 400 individual storage cells", "Ghorfas are arranged in tiers up to four stories high", "Filming location for Star Wars: Episode I", "Traditional storage site for grain and olive oil", "Located about 20 kilometers south of the city of Tataouine"],
      es: ["El Ksar tiene unas 400 ghorfas (cámaras de almacenamiento).", "Tiene cuatro pisos.", "Los muros exteriores tienen 8 metros de altura.", "Las partes más antiguas datan del siglo XV.", "La instalación tiene dos patios interiores.", "Las ghorfas están abovedadas y hechas de ladrillos de barro."],
      pt: ["O Ksar tem cerca de 400 ghorfas (câmaras de armazenamento).", "Tem quatro andares.", "As paredes exteriores têm 8 metros de altura.", "As partes mais antigas datam do século XV.", "A instalação tem dois pátios interiores.", "As ghorfas são abobadadas e feitas de tijolos de barro."],
      fr: ["Le Ksar compte environ 400 ghorfas (chambres de stockage).", "Il comporte quatre étages.", "Les murs extérieurs mesurent 8 mètres de haut.", "Les parties les plus anciennes datent du XVe siècle.", "L'installation comprend deux cours intérieures.", "Les ghorfas sont voûtées et faites de briques de terre."],
